fn parse_pair_sum(a: &str, b: &str) -> String {
    fn inner(a: &str, b: &str) -> Result<i32, std::num::ParseIntError> {
        let x = a.parse::<i32>()?;
        let y = b.parse::<i32>()?;
        Ok(x + y)
    }
    match inner(a, b) {
        Ok(v) => format!("{}", v),
        Err(_) => String::from("ERR"),
    }
}

