fn split_at_checked(s: &str, mid: usize) -> String {
    if mid > s.len() || !s.is_char_boundary(mid) {
        return String::from("ERR");
    }
    let (l, r) = s.split_at(mid);
    format!("{}|{}", l, r)
}

